<?php
use App\Services\{AuthService,DeckService,CardService,BattleService,PlayerService};
use App\Core\Database;
$auth=new AuthService();$u=$auth->register(['name'=>'Duelista teste','email'=>'test@example.org','password'=>'SenhaForte123!']);$userId=$u['id'];
test('Cadastro cria conta, coleção e deck inicial',function()use($u,$userId){check(!isset($u['password_hash']));same(6,count((new App\Repositories\CardRepository())->collection($userId)));same(12,(new DeckService())->all($userId)[0]['count']);same(0,(new PlayerService())->statistics($userId)['battles']);});
test('Login verifica senha e normaliza e-mail',function()use($auth,$userId){same($userId,$auth->login(['email'=>'TEST@example.org','password'=>'SenhaForte123!'])['id']);rejects(fn()=>$auth->login(['email'=>'test@example.org','password'=>'invalida']),401);});
test('Cadastro valida e-mail, senha e duplicidade',function()use($auth){rejects(fn()=>$auth->register(['name'=>'A','email'=>'errado','password'=>'1']));rejects(fn()=>$auth->register(['name'=>'Teste','email'=>'test@example.org','password'=>'SenhaForte123!']));});
test('Senha armazenada usa hash seguro',function()use($userId){$user=(new App\Repositories\UserRepository())->find($userId);check(password_verify('SenhaForte123!',$user['password_hash']));check($user['password_hash']!=='SenhaForte123!');});
test('Visitante não pode entrar por senha',function()use($auth){$g=$auth->register(['name'=>'Visitante','email'=>'guest@example.org','password'=>'SenhaForte123!'],true);rejects(fn()=>$auth->login(['email'=>$g['email'],'password'=>'SenhaForte123!']),401);});
$other=$auth->register(['name'=>'Outro jogador','email'=>'other@example.org','password'=>'SenhaForte123!']);$deckId=(new DeckService())->all($userId)[0]['id'];
test('Deck rejeita quantidade, carta repetida e acesso de outro dono',function()use($userId,$deckId,$other){$svc=new DeckService();rejects(fn()=>$svc->save($userId,['name'=>'Teste','cards'=>[['card_id'=>1,'quantity'=>4]]]));rejects(fn()=>$svc->save($userId,['name'=>'Teste','cards'=>[['card_id'=>1,'quantity'=>3],['card_id'=>1,'quantity'=>3]]]));rejects(fn()=>$svc->save($other['id'],['name'=>'Teste','cards'=>[]],$deckId),404);});
test('Deck válido pode ser criado e editado',function()use($userId,$cards){$d=(new DeckService())->save($userId,['name'=>'Deck customizado','cards'=>array_map(fn($c)=>['card_id'=>$c['id'],'quantity'=>2],array_values($cards))]);same(12,$d['count']);$d=(new DeckService())->save($userId,['name'=>'Deck renomeado','cards'=>$d['cards']],$d['id']);same('Deck renomeado',$d['name']);});
$svc=new BattleService();$state=$svc->create($userId,$deckId);$battleId=$state['id'];
test('Partida oculta mão da IA, deck e snapshot interno',function()use($state){check(!isset($state['ai']['hand'],$state['ai']['deck'],$state['player']['deck'],$state['card_snapshot']));same(5,$state['ai']['hand_count']);});
test('Criação retoma partida ativa sem duplicar',function()use($svc,$userId,$deckId,$battleId){$resumed=$svc->create($userId,$deckId);same($battleId,$resumed['id']);check(!isset($resumed['card_snapshot']));});
test('Partida é isolada por jogador e rejeita versão antiga',function()use($svc,$userId,$other,$battleId){rejects(fn()=>$svc->get($battleId,$other['id']),404);rejects(fn()=>$svc->action($battleId,$userId,'end-turn',['version'=>999]),409);});
test('Ações persistem estado, eventos, turnos e criaturas',function()use($svc,$userId,$battleId,$cards){$s=$svc->get($battleId,$userId);$id=current(array_filter($s['player']['hand'],fn($id)=>$cards[$id]['cost']<=3));$old=$s['version'];$s=$svc->action($battleId,$userId,'summon',['card_id'=>$id,'version'=>$old,'damage'=>999999]);same($old+1,$s['version']);same(1,count($svc->get($battleId,$userId)['player']['field']));rejects(fn()=>$svc->action($battleId,$userId,'end-turn',['version'=>$old]),409);$q=Database::connection()->prepare('SELECT COUNT(*) FROM battle_actions WHERE battle_id=?');$q->execute([$battleId]);check((int)$q->fetchColumn()>=2);});
test('Dano enviado pelo cliente é ignorado',function()use($svc,$userId,$battleId){$s=$svc->get($battleId,$userId);$m=$s['player']['field'][0];$s=$svc->action($battleId,$userId,'attack',['attacker_id'=>$m['id'],'version'=>$s['version'],'damage'=>99999999]);check($s['ai']['hp']>2000);check($s['ai']['hp']<4000);});
test('Simulação completa contra IA salva resultado uma única vez',function()use($svc,$userId,$battleId,$cards){$s=$svc->get($battleId,$userId);$guard=0;while($s['status']==='active'&&$guard++<100){if(!$s['player']['summoned']&&count($s['player']['field'])<3){$valid=array_filter($s['player']['hand'],fn($id)=>$cards[$id]['cost']<=$s['player']['energy']);if($valid)$s=$svc->action($battleId,$userId,'summon',['card_id'=>reset($valid),'version'=>$s['version']]);}foreach($s['player']['field']as$m){if($s['status']!=='active')break;if(!$m['attacked'])$s=$svc->action($battleId,$userId,'attack',['attacker_id'=>$m['id'],'target_id'=>$s['ai']['field'][0]['id']??null,'version'=>$s['version']]);}if($s['status']==='active')$s=$svc->action($battleId,$userId,'end-turn',['version'=>$s['version']]);}same('finished',$s['status']);same(1,(new PlayerService())->statistics($userId)['battles']);rejects(fn()=>$svc->action($battleId,$userId,'end-turn',['version'=>$s['version']]));same(1,(new PlayerService())->statistics($userId)['battles']);});
test('Cadastro administrativo valida atributos e recursos',function()use($cards){$c=$cards[1];$data=$c+['ability_code'=>'burn','ability_name'=>'Sopro novo','ability_description'=>'Dano adicional de brasas.'];$data['slug']='teste-original';$data['name']='Criatura original';$created=(new CardService())->save($data);check($created['id']>6);$data['attack']=-5;rejects(fn()=>(new CardService())->save($data));$data['attack']=1000;$data['image_url']='../../.env';rejects(fn()=>(new CardService())->save($data));});
test('Middleware exige sessão e perfil de administrador',function()use($userId){$_SESSION=[];rejects(fn()=>App\Middleware\Auth::user(),401);$_SESSION['user_id']=$userId;rejects(fn()=>App\Middleware\Auth::admin(),403);Database::connection()->prepare("UPDATE users SET role='admin' WHERE id=?")->execute([$userId]);same('admin',App\Middleware\Auth::admin()['role']);});

test('Auditoria pública oculta compras da mão adversária',function()use($svc,$userId,$deckId){$s=$svc->create($userId,$deckId);$s=$svc->action($s['id'],$userId,'end-turn',['version'=>$s['version']]);$events=(new App\Repositories\BattleRepository())->history($s['id'],$userId);foreach($events as$event){$payload=$event['payload'];if($payload['type']==='draw'&&$payload['side']==='ai')check(!isset($payload['card_id']));}check(count($s['catalog'])>=6);});
test('Rate limiting rejeita excesso de ações críticas',function(){$_SERVER['REMOTE_ADDR']='test-'.bin2hex(random_bytes(8));App\Middleware\RateLimit::check('/api/auth/login',2);App\Middleware\RateLimit::check('/api/auth/login',2);rejects(fn()=>App\Middleware\RateLimit::check('/api/auth/login',2),429);});
